(370, 1, '2018-10-20 17:09:48', '2018-10-20 14:09:48', 'a:10:{s:4:\"type\";s:8:\"repeater\";s:12:\"instructions\";s:0:\"\";s:8:\"required\";i:0;s:17:\"conditional_logic\";i:0;s:7:\"wrapper\";a:3:{s:5:\"width\";s:0:\"\";s:5:\"class\";s:0:\"\";s:2:\"id\";s:0:\"\";}s:9:\"collapsed\";s:0:\"\";s:3:\"min\";s:0:\"\";s:3:\"max\";s:0:\"\";s:6:\"layout\";s:5:\"table\";s:12:\"button_label\";s:0:\"\";}', 'Факты', 'факты', 'publish', 'closed', 'closed', '', 'field_5bcb370da7903', '', '', '2018-10-20 17:09:48', '2018-10-20 14:09:48', '', 62, 'http://ballwatch.aliveliyev.com/?post_type=acf-field&p=370', 3, 'acf-field', '', 0),
(371, 1, '2018-10-20 17:09:48', '2018-10-20 14:09:48', 'a:10:{s:4:\"type\";s:4:\"text\";s:12:\"instructions\";s:0:\"\";s:8:\"required\";i:0;s:17:\"conditional_logic\";i:0;s:7:\"wrapper\";a:3:{s:5:\"width\";s:0:\"\";s:5:\"class\";s:0:\"\";s:2:\"id\";s:0:\"\";}s:13:\"default_value\";s:0:\"\";s:11:\"placeholder\";s:0:\"\";s:7:\"prepend\";s:0:\"\";s:6:\"append\";s:0:\"\";s:9:\"maxlength\";s:0:\"\";}', 'Факт', 'факт', 'publish', 'closed', 'closed', '', 'field_5bcb3722a7904', '', '', '2018-10-20 17:09:48', '2018-10-20 14:09:48', '', 370, 'http://ballwatch.aliveliyev.com/?post_type=acf-field&p=371', 0, 'acf-field', '', 0),
