(708, 1, '2018-10-22 02:34:55', '2018-10-21 23:34:55', 'a:10:{s:4:\"type\";s:8:\"repeater\";s:12:\"instructions\";s:0:\"\";s:8:\"required\";i:0;s:17:\"conditional_logic\";i:0;s:7:\"wrapper\";a:3:{s:5:\"width\";s:0:\"\";s:5:\"class\";s:0:\"\";s:2:\"id\";s:0:\"\";}s:9:\"collapsed\";s:0:\"\";s:3:\"min\";s:0:\"\";s:3:\"max\";s:0:\"\";s:6:\"layout\";s:5:\"table\";s:12:\"button_label\";s:0:\"\";}', 'Галлерея', 'галлерея', 'publish', 'closed', 'closed', '', 'field_5bcd0cf61c34f', '', '', '2018-10-22 02:34:55', '2018-10-21 23:34:55', '', 76, 'http://ballwatch.aliveliyev.com/?post_type=acf-field&p=708', 2, 'acf-field', '', 0),
